  "auxiliary.transient_retries": {"type":"int","default":2,"doc":"Same-provider retries for a transient transport blip (connection reset / timeout / 5xx / 408) on ANY auxiliary call before falling back. Default 2 (→ 3 total attempts), clamped [0,6]. Matters most for pinned calls like MoA reference advisors, where provider fallback is not a meaningful recovery, so an unretried blip silently loses the call.","group":"auxiliary","effect":"session"},
