  "tts.elevenlabs.voice_id": {"type":"str","default":"pNInz6obpgDQGcFmaJgB","doc":"Adam","group":"tts","effect":"live"},
  "tts.gemini.audio_tags": {"type":"bool","default":false,"doc":"When true, Gemini 3.1 TTS uses a hidden auxiliary-model rewrite pass to insert freeform square-bracket audio tags into the TTS script. Visible chat replies are unchanged.","group":"tts","effect":"live"},
  "tts.gemini.model": {"type":"str","default":"gemini-2.5-flash-preview-tts","doc":"","group":"tts","effect":"live"},
  "tts.gemini.persona_prompt_file": {"type":"str","default":"","doc":"Optional local Markdown/text file with Gemini TTS performance direction. It may include AUDIO PROFILE, SCENE, DIRECTOR'S NOTES, SAMPLE CONTEXT, and either a `{transcript}` placeholder or no transcript section; Hermes appends the live transcript when absent.","group":"tts","effect":"live"},
  "tts.gemini.voice": {"type":"str","default":"Kore","doc":"","group":"tts","effect":"live"},
  "tts.kittentts.model": {"type":"str","default":"KittenML/kitten-tts-nano-0.8-int8","doc":"nano 25MB; micro 41MB; mini 80MB","group":"tts","effect":"live"},
  "tts.kittentts.voice": {"type":"str","default":"Jasper","doc":"","group":"tts","effect":"live"},
  "tts.minimax.model": {"type":"str","default":"speech-02-hd","doc":"","group":"tts","effect":"live"},
  "tts.minimax.voice_id": {"type":"str","default":"English_expressive_narrator","doc":"","group":"tts","effect":"live"},
  "tts.mistral.model": {"type":"str","default":"voxtral-mini-tts-2603","doc":"","group":"tts","effect":"live"},
  "tts.mistral.voice_id": {"type":"str","default":"c69964a6-ab8b-4f8a-9465-ec0925096ec8","doc":"Paul - Neutral","group":"tts","effect":"live"},
