  "tts.neutts.model": {"type":"str","default":"neuphonic/neutts-air-q4-gguf","doc":"HuggingFace model repo","group":"tts","effect":"live"},
  "tts.neutts.ref_audio": {"type":"str","default":"","doc":"Path to reference voice audio (empty = bundled default)","group":"tts","effect":"live"},
  "tts.neutts.ref_text": {"type":"str","default":"","doc":"Path to reference voice transcript (empty = bundled default)","group":"tts","effect":"live"},
  "tts.openai.model": {"type":"str","default":"gpt-4o-mini-tts","doc":"","group":"tts","effect":"live"},
  "tts.openai.voice": {"type":"str","default":"alloy","doc":"","group":"tts","effect":"live"},
  "tts.piper.voice": {"type":"str","default":"en_US-lessac-medium","doc":"Voice name (e.g. \"en_US-lessac-medium\") downloaded on first use, OR an absolute path to a pre-downloaded .onnx file. Full voice list: https://github.com/OHF-Voice/piper1-gpl/blob/main/docs/VOICES.md","group":"tts","effect":"live"},
  "tts.provider": {"type":"str","default":"edge","doc":"Set explicitly to pin a backend: \"edge\" (free) | \"elevenlabs\" (premium) | \"openai\" | \"xai\" | \"minimax\" | \"mistral\" | \"gemini\" | \"deepinfra\" | \"neutts\" (local) | \"kittentts\" (local) | \"piper\" (local)","group":"tts","effect":"live"},
  "tts.xai.auto_speech_tags": {"type":"bool","default":false,"doc":"insert expressive audio tags via LLM rewrite","group":"tts","effect":"live"},
  "tts.xai.bit_rate": {"type":"int","default":128000,"doc":"MP3 bitrate; only applies when codec=mp3","group":"tts","effect":"live"},
  "tts.xai.language": {"type":"str","default":"en","doc":"BCP-47 code (\"en\", \"pt-BR\") or \"auto\"","group":"tts","effect":"live"},
  "tts.xai.optimize_streaming_latency": {"type":"int","default":0,"doc":"0–2, trades quality for lower latency","group":"tts","effect":"live"},
  "tts.xai.sample_rate": {"type":"int","default":24000,"doc":"22050 / 24000 / 44100 / 48000","group":"tts","effect":"live"},
  "tts.xai.speed": {"type":"float","default":1,"doc":"0.7–1.5, playback speed","group":"tts","effect":"live"},
  "tts.xai.voice_id": {"type":"str","default":"eve","doc":"or custom voice ID — see https://docs.x.ai/developers/model-capabilities/audio/custom-voices","group":"tts","effect":"live"},
  "updates.backup_keep": {"type":"int","default":5,"doc":"How many full pre-update backup zips to retain (mode ``full``). Older ones are pruned automatically after each successful backup. Values below 1 are floored to 1 — the backup just created is always preserved. The quick snapshot always keeps exactly 1.","group":"updates","effect":"live"},
  "updates.non_interactive_local_changes": {"type":"str","default":"stash","doc":"What `hermes update` does with uncommitted local changes to the source tree when it runs NON-interactively — i.e. triggered from the desktop/chat app or the gateway, where there's no TTY to answer a restore prompt. Interactive (terminal) updates are unaffected: they always stash the changes and ask whether to restore, exactly as they always have.   \"stash\"   — auto-stash the changes, pull, then auto-restore them               on top of the updated code (the safe default; nothing               is ever lost — conflicts are preserved in a git stash).   \"discard\" — auto-stash the changes and throw the stash away after               the pull. Use this only if you never intend to keep               local edits to the source tree on this machine.               Stash-and-drop (not `reset --hard` + `clean -fd`) so               ignored paths — node_modules, venv, build outputs —               are never touched.","group":"updates","effect":"live"},
  "updates.pre_update_backup": {"type":"str","default":"quick","doc":"Pre-update safety backup — ONE consolidated mechanism, three modes:    quick (default) — snapshot critical small state files (pairing     JSONs, cron jobs, config.yaml, .env, auth.json, per-profile     DBs) into <HERMES_HOME>/state-snapshots/ before the update.     Files over 1 GiB (e.g. a bloated state.db) are skipped with a     warning so the snapshot stays fast. Restore via ``/snapshot``.     This is the #15733 (lost pairing data) / #34600 (emptied cron     jobs) safety net.   full — the quick snapshot PLUS a full ``hermes backup``-style zip     of HERMES_HOME into <HERMES_HOME>/backups/, restorable with     ``hermes import``. Can add minutes on large homes. This is the     #48200 (wrong-path wipe) safety net. ``--backup`` forces this     for a single run.   off — no pre-update backup of any kind. ``--no-backup`` forces     this for a single run.  Legacy boolean values are honored: true -> full, false -> off.","group":"updates","effect":"live"},
  "updates.refresh_cua_driver": {"type":"bool","default":true,"doc":"Refresh an already-installed cua-driver during `hermes update`. The refresh is best-effort and macOS-only. Turn this off if the upstream installer is not appropriate for the machine, for example on non-admin accounts where `/Applications` is not writable.","group":"updates","effect":"live"},
  "vertex.project_id": {"type":"str","default":"","doc":"GCP project ID. Empty → use the project_id embedded in the service account JSON (or ADC-resolved project).","group":"vertex","effect":"live"},
  "vertex.region": {"type":"str","default":"global","doc":"Vertex region. \"global\" is required for the Gemini 3.x preview models (regional endpoints silently 404 them). Override to a regional value (e.g. \"us-central1\") only if your models are pinned to a region.","group":"vertex","effect":"live"},
  "voice.auto_tts": {"type":"bool","default":false,"doc":"","group":"voice","effect":"live"},
  "voice.barge_in": {"type":"bool","default":true,"doc":"Stop TTS playback when the user starts talking","group":"voice","effect":"live"},
  "voice.beep_enabled": {"type":"bool","default":true,"doc":"Play record start/stop beeps in CLI voice mode","group":"voice","effect":"live"},
  "voice.max_recording_seconds": {"type":"int","default":120,"doc":"","group":"voice","effect":"live"},
  "voice.record_key": {"type":"str","default":"ctrl+b","doc":"","group":"voice","effect":"live"},
  "voice.silence_duration": {"type":"float","default":3,"doc":"Seconds of silence before auto-stop","group":"voice","effect":"live"},
  "voice.silence_threshold": {"type":"int","default":200,"doc":"RMS below this = silence (0-32767)","group":"voice","effect":"live"},
  "voice.stop_phrases": {"type":"list","default":["stop"],"doc":"Saying EXACTLY one of these phrases (and nothing else) ends the voice chat instead of being sent to the agent. Case-insensitive, surrounding punctuation ignored. Set [] to disable.","group":"voice","effect":"live"},
  "web.backend": {"type":"str","default":"","doc":"shared fallback — applies to both search and extract","group":"web","effect":"live"},
