  "web.extract_char_limit": {"type":"int","default":15000,"doc":"per-page char budget for web_extract; larger pages truncate + store full text in cache/web","group":"web","effect":"live"},
  "web.search_backend": {"type":"str","default":"","doc":"per-capability override for web_search (e.g. \"searxng\")","group":"web","effect":"live"},
  "whatsapp": {"type":"dict","default":{},"doc":"WhatsApp platform settings (gateway mode)","group":"general","effect":"live"},
  "x_search.model": {"type":"str","default":"grok-4.5","doc":"xAI model used for the Responses call. grok-4.5 is the recommended default; any Grok model with x_search tool access works.","group":"x_search","effect":"live"},
  "x_search.reasoning_effort": {"type":"null","default":null,"doc":"Optional reasoning effort sent to xAI Responses API models that support it. Leave null to preserve the selected model's default.","group":"x_search","effect":"live"},
  "x_search.retries": {"type":"int","default":2,"doc":"Number of automatic retries on 5xx / ReadTimeout / ConnectionError. Each retry backs off (1.5x attempt seconds, capped at 5s).","group":"x_search","effect":"live"},
  "x_search.timeout_seconds": {"type":"int","default":180,"doc":"Request timeout in seconds (minimum 30). x_search can take 60-120s for complex queries — the default is generous.","group":"x_search","effect":"live"},
